 function setLanguage(value){if(value!=='auto'&&!normalLang(value))return false;const ok=value==='auto'?(safeSet(LANG_KEY,'auto')):safeSet(LANG_KEY,value);if(!ok)return false;apply();dispatch('emlove:language-change',{language:language()});return true}
