 function crisisSummary(){const l=language(),dict=SUPPORT[l]||SUPPORT.en,c=country();if(!c)return dict.unknownRegion+' '+dict.note;const region=dict.countries[c];return region?region.contacts.map(x=>x.number+' ('+x.label+')').join('; '):dict.unknownRegion+' '+dict.note}
